def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            queue = [(r, c)]
            seen.add((r, c))
            cells = []
            for x, y in queue:
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dx, y + dy
                    if 0 <= a < h and 0 <= b < w and (a, b) not in seen and grid[a][b] == color:
                        seen.add((a, b))
                        queue.append((a, b))
            min_r = min(x for x, y in cells)
            min_c = min(y for x, y in cells)
            shape = tuple(sorted((x - min_r, y - min_c) for x, y in cells))
            edges = set()
            for x, y in cells:
                if x == 0: edges.add('top')
                if x == h - 1: edges.add('bottom')
                if y == 0: edges.add('left')
                if y == w - 1: edges.add('right')
            components.append({'color': color, 'cells': cells, 'shape': shape,
                               'size': len(cells), 'edges': edges})
    matches = []
    for target in components:
        for sample in components:
            if sample['color'] != target['color'] and sample['edges'] and sample['shape'] == target['shape']:
                matches.append((target, sample))
    if not matches:
        return [row[:] for row in grid]
    strong = [pair for pair in matches if len(pair[1]['edges']) >= 2]
    target, sample = max(strong or matches,
                         key=lambda pair: (len(pair[1]['edges']) >= 2, pair[0]['size'], len(pair[1]['edges'])))
    destinations = [component for component in components
                    if component is not sample and len(component['edges']) >= 2]
    if not destinations:
        destinations = [component for component in components
                        if component is not sample and component['edges']]
    if not destinations:
        return [row[:] for row in grid]
    color = max(destinations, key=lambda component: component['size'])['color']
    output = [row[:] for row in grid]
    for r, c in target['cells']:
        output[r][c] = color
    return output
